const events = $input.first().json.result || [];

// Filtrar apenas eventos com comentário do n8n (remediações automáticas)
const remediated = events.filter(e => 
  e.acknowledges && e.acknowledges.some(a => a.message && a.message.includes('[n8n]'))
);

const total = events.length;
const totalRemediated = remediated.length;
const totalPending = total - totalRemediated;

const now = new Date();
const yesterday = new Date(now.getTime() - 86400000);
const dateStr = yesterday.toLocaleDateString('pt-BR');

// Montar tabela de eventos
let rows = '';
for (const e of remediated.slice(0, 10)) {
  const time = new Date(e.clock * 1000).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  const msg = e.acknowledges.find(a => a.message?.includes('[n8n]'))?.message || '';
  rows += `| ${time} | ${e.name?.substring(0, 40)} | Remediado | ${msg.substring(0, 60)} |\n`;
}

return [{
  json: {
    date: dateStr,
    total,
    totalRemediated,
    totalPending,
    rows,
    hasRemediated: totalRemediated > 0
  }
}];

